/**
 * Brand / network icons — pulled verbatim from the Figma "Reporting" file.
 *
 * Source: every icon below is a direct export from Figma's icon set and is
 * composed exactly the way Figma renders it — a 24×24 outer tile with one or
 * more absolutely-positioned child `<svg>` layers. Each layer's inset
 * percentages match Figma's own frame layout (pulled via get_design_context
 * on Frame 1139:172946, the network filter row).
 *
 * Raw SVG sources live in `./svg/brand-*.svg` (see the brand-* files) and the
 * inline paths below are verbatim copies. Stroke icons (`grid_profiles`) pass
 * stroke color through the `--stroke-0` CSS variable so callers can recolor
 * them (e.g. purple on a selected tile).
 *
 * Sizing: every icon is rendered at `size × size` (default 24). The inset
 * percentages scale proportionally, so a 16×16 render keeps the Figma
 * aspect and positioning exactly.
 *
 * DO NOT hand-author additions — re-run Figma MCP (`get_design_context`) and
 * save the exported SVG under `./svg/brand-<name>.svg` before adding a new
 * icon here.
 */

import { CSSProperties, ReactNode } from 'react';

export interface NetworkIconProps {
  /** Outer tile dimension in px. Default 24 to match Figma's icon-l tile. */
  size?: number;
  className?: string;
  /**
   * Stroke color for monochrome (library) brand icons like `IconNetworkAll`.
   * Ignored by multi-color brand logos which have baked-in fills.
   */
  color?: string;
}

// Shared tile wrapper — relative 24×24 footprint; children are absolutely
// inset to match Figma's node tree. `overflow` defaults to `hidden` because
// Figma frames that wrap multi-layer brand icons set `overflow-clip`, but
// grid_profiles adds a `-3.95%` outset for stroke margin so that one uses
// visible.
function Tile({
  size,
  className,
  overflow,
  style,
  children,
}: {
  size: number;
  className?: string;
  overflow: 'hidden' | 'visible';
  style?: CSSProperties;
  children: ReactNode;
}) {
  return (
    <span
      className={className}
      aria-hidden="true"
      style={{
        position: 'relative',
        display: 'inline-block',
        width: size,
        height: size,
        overflow,
        flexShrink: 0,
        ...style,
      }}
    >
      {children}
    </span>
  );
}

// Absolutely-positioned child layer inside the tile. `inset` is a CSS string
// matching Figma's `inset-[T_R_B_L]` value (or a single value for symmetric).
function Layer({ inset, children }: { inset: string; children: ReactNode }) {
  return (
    <span style={{ position: 'absolute', inset, display: 'block' }}>
      {children}
    </span>
  );
}

// Every layer SVG fills its parent Layer exactly; the Layer controls position.
const LAYER_SVG_PROPS = {
  width: '100%',
  height: '100%',
  fill: 'none',
  xmlns: 'http://www.w3.org/2000/svg',
  preserveAspectRatio: 'none',
  style: { display: 'block' } as CSSProperties,
} as const;

// ───────────────────────────────────────────────────────────────────────────
// All / grid_profiles — Figma 2:140.
// Single stroke path. Tile overflow is VISIBLE because the native viewBox
// (20.5 × 20.5) includes 0.75 stroke margin on each side; Figma wraps it in
// an outer inset-[-3.95%] layer to let the stroke "bleed" out. Stroke color
// flows through `--stroke-0` so a selected tile can switch to BRAND/primary.
// ───────────────────────────────────────────────────────────────────────────
export function IconNetworkAll({ size = 24, className, color = '#201E24' }: NetworkIconProps) {
  const style: CSSProperties & Record<'--stroke-0', string> = {
    ['--stroke-0']: color,
  };
  return (
    <Tile size={size} className={className} overflow="hidden" style={style}>
      <Layer inset="8.33% 12.5% 12.5% 8.33%">
        <Layer inset="-3.95%">
          <svg viewBox="0 0 20.5 20.5" {...LAYER_SVG_PROPS} overflow="visible">
            <path
              d="M16.25 12.75V19.75M19.75 16.25H12.75M1.75 12.75H8.75V19.75H1.75V12.75ZM16.25 8.75C14.317 8.75 12.75 7.183 12.75 5.25C12.75 3.317 14.317 1.75 16.25 1.75C18.183 1.75 19.75 3.317 19.75 5.25C19.75 7.183 18.183 8.75 16.25 8.75ZM0.75 5.25L5.25 0.75L9.75 5.25L5.25 9.75L0.75 5.25Z"
              stroke="var(--stroke-0, #201E24)"
              strokeWidth={1.5}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </Layer>
      </Layer>
    </Tile>
  );
}

